// base = 100 req/s, failureRate causes a retry each, up to maxAttempts
const base = 100;
const failureRate = 0.4;
const maxAttempts = 3;
const budgetFraction = 0.10; // retries may add at most 10% over base

// extra attempts generated beyond the first, per request, under independent failures
let extraPerReq = 0;
let pFail = 1;
for (let attempt = 1; attempt < maxAttempts; attempt++) {
  pFail *= failureRate;          // prob the previous attempt(s) all failed
  extraPerReq += pFail;          // this retry is offered with that prob
}
const extraLoad = base * extraPerReq;        // extra req/s from retries
const addedFraction = extraLoad / base;       // fraction over base
console.log(addedFraction > budgetFraction ? 'VIOLATED' : 'WITHIN-BUDGET');
